const rate=(part:number,total:number)=>total?round(part/total*100,1):0;
const percentile=(values:number[],fraction:number)=>{const sorted=values.filter((value)=>Number.isFinite(value)&&value>=0).sort((a,b)=>a-b);if(!sorted.length)return null;const index=Math.min(sorted.length-1,Math.max(0,Math.ceil(sorted.length*fraction)-1));return Math.round(sorted[index]);};
